// WaveShaper: Seven curves, drive/output dB, tone filters, bias and mix. Legacy tone factor legacyToneFactor is source-only and scales filter cutoff; it is not FIR oversampling.
// Legacy reference: dsp/core/nodes/WaveShaperNode.cpp
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  waveShaper as waveShaperDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    waveShaper_curve: {
      "path": "/primitives/wave-shaper/node/0",
      "label": "Curve",
      "group": "WaveShaper",
      "min": 0,
      "max": 6,
      "default": 0,
      "choices": [
        "Tanh",
        "Asymmetric",
        "Arctangent",
        "Hard clip",
        "Fold",
        "Soft clip",
        "Diode"
      ]
    },
    waveShaper_driveDb: {
      "path": "/primitives/wave-shaper/node/1",
      "label": "Drive dB",
      "group": "WaveShaper",
      "min": 0,
      "max": 40,
      "default": 12
    },
    waveShaper_outputDb: {
      "path": "/primitives/wave-shaper/node/2",
      "label": "Output dB",
      "group": "WaveShaper",
      "min": -20,
      "max": 20,
      "default": -6
    },
    waveShaper_preFilterHz: {
      "path": "/primitives/wave-shaper/node/3",
      "label": "Pre-filter Hz (0 disables)",
      "group": "WaveShaper",
      "min": 0,
      "max": 20000,
      "default": 2000
    },
    waveShaper_postFilterHz: {
      "path": "/primitives/wave-shaper/node/4",
      "label": "Post-filter Hz (0 disables)",
      "group": "WaveShaper",
      "min": 0,
      "max": 20000,
      "default": 4000
    },
    waveShaper_bias: {
      "path": "/primitives/wave-shaper/node/5",
      "label": "Bias",
      "group": "WaveShaper",
      "min": -1,
      "max": 1,
      "default": 0
    },
    waveShaper_wetMix: {
      "path": "/primitives/wave-shaper/node/6",
      "label": "Wet mix",
      "group": "WaveShaper",
      "min": 0,
      "max": 1,
      "default": 1
    },
  };

  // Audio inputs and outputs — the host supplies the external audio input.
  const graph = createGraphWorkspace().setInputSource('external');
  const input = graph.input.output('out');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const waveShaper = graph.add(waveShaperDefinition.type, {"id":4});
  graph.registerInstance('/primitives/wave-shaper/node', waveShaper);
  waveShaper.parameter('curve').expose(controls.waveShaper_curve);
  waveShaper.parameter('driveDb').expose(controls.waveShaper_driveDb);
  waveShaper.parameter('outputDb').expose(controls.waveShaper_outputDb);
  waveShaper.parameter('preFilterHz').expose(controls.waveShaper_preFilterHz);
  waveShaper.parameter('postFilterHz').expose(controls.waveShaper_postFilterHz);
  waveShaper.parameter('bias').expose(controls.waveShaper_bias);
  waveShaper.parameter('wetMix').expose(controls.waveShaper_wetMix);
  waveShaper.parameter('legacyToneFactor').set(2);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(input, waveShaper.input('audio'));
  graph.connect(waveShaper.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.waveShaper_curve,
    controls.waveShaper_driveDb,
    controls.waveShaper_outputDb,
    controls.waveShaper_preFilterHz,
    controls.waveShaper_postFilterHz,
    controls.waveShaper_bias,
    controls.waveShaper_wetMix
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
